BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD availableBytes = 0;
    DWORD bytesRead = 0;
    DWORD totalBytes = 0;
    DWORD readSize = 0;
    LPVOID buffer = NULL;
    PCHAR data = NULL;
    PCHAR workingDir = NULL;
    PCHAR cmdLine = NULL;
    PCHAR stdinInput = NULL;
    BOOL result = FALSE;

    // Check if bytes are available in the pipe
    if (!PeekNamedPipe(pipe, NULL, 0, &bytesRead, &availableBytes, NULL) || availableBytes == 0) {
        LogError("No bytes available in the named pipe.");
        return FALSE;
    }

    // Allocate memory for the buffer
    buffer = VirtualAlloc(NULL, availableBytes, MEM_COMMIT, PAGE_READWRITE);
    if (buffer == NULL) {
        LogError("Memory allocation failed.");
        return FALSE;
    }

    data = (PCHAR)buffer;

    // Read data from the pipe
    if (!ReadFile(pipe, buffer, availableBytes, &readSize, NULL) || readSize != availableBytes) {
        LogError("Failed to read all bytes from the named pipe.");
        VirtualFree(buffer, 0, MEM_RELEASE);
        return FALSE;
    }

    // Check for NULL termination
    if (data[readSize - 1] != '\0') {
        LogError("Data read from pipe is not NULL terminated.");
        VirtualFree(buffer, 0, MEM_RELEASE);
        return FALSE;
    }

    // Parse the data
    workingDir = data;
    if (workingDir[0] == '\0') {
        LogError("Working directory is invalid.");
        VirtualFree(buffer, 0, MEM_RELEASE);
        return FALSE;
    }

    cmdLine = workingDir + strlen(workingDir) + 1;
    if (cmdLine[0] == '\0') {
        LogError("Command line is invalid.");
        VirtualFree(buffer, 0, MEM_RELEASE);
        return FALSE;
    }

    stdinInput = cmdLine + strlen(cmdLine) + 1;
    if (stdinInput[0] == '\0') {
        LogError("Standard input is invalid.");
        VirtualFree(buffer, 0, MEM_RELEASE);
        return FALSE;
    }

    // Populate the STARTUP_DATA structure
    sud->workingDir = workingDir;
    sud->cmdLine = cmdLine;
    sud->stdinInput = stdinInput;

    result = TRUE;

    // Clean up memory if necessary (if we need to release it later)
    sud->buffer = buffer;

    return result;
}

