BOOL RetrieveStartupData(HANDLE pipe, STARTUP_DATA* sud) {
    DWORD bytesAvailable = 0;
    DWORD bytesRead = 0;
    LPVOID buffer = NULL;

    if (!PeekNamedPipe(pipe, NULL, 0, NULL, &bytesAvailable, NULL)) {
        LogError("PeekNamedPipe failed");
        return FALSE;
    }

    if (bytesAvailable == 0) {
        LogError("No data available in the pipe");
        return FALSE;
    }

    buffer = HeapAlloc(GetProcessHeap(), GMEM_FIXED, bytesAvailable);
    if (buffer == NULL) {
        LogError("Memory allocation failed");
        return FALSE;
    }

    if (!ReadFile(pipe, buffer, bytesAvailable, &bytesRead, NULL) || bytesRead != bytesAvailable) {
        LogError("Failed to read data from pipe");
        HeapFree(GetProcessHeap(), 0, buffer);
        return FALSE;
    }

    char* data = (char*)buffer;
    if (data[bytesRead - 1] != '\0') {
        LogError("Pipe data not NULL-terminated");
        HeapFree(GetProcessHeap(), 0, buffer);
        return FALSE;
    }

    char* workingDir = _strdup(data);
    if (workingDir == NULL) {
        LogError("Failed to duplicate working directory string");
        HeapFree(GetProcessHeap(), 0, buffer);
        return FALSE;
    }

    char* cmdLine = strchr(data, '\n');
    if (cmdLine == NULL) {
        LogError("Command line not found in pipe data");
        HeapFree(GetProcessHeap(), 0, buffer);
        HeapFree(GetProcessHeap(), 0, workingDir);
        return FALSE;
    }
    cmdLine++; // Move past the newline
    *cmdLine++ = '\0'; // Terminate working directory

    char* stdinData = strchr(cmdLine, '\n');
    if (stdinData == NULL) {
        LogError("Standard input data not found in pipe data");
        HeapFree(GetProcessHeap(), 0, buffer);
        HeapFree(GetProcessHeap(), 0, workingDir);
        HeapFree(GetProcessHeap(), 0, cmdLine - 1);
        return FALSE;
    }
    *stdinData++ = '\0'; // Terminate command line

    sud->workingDirectory = workingDir;
    sud->commandLine = cmdLine;
    sud->standardInput = stdinData;

    return TRUE;
}

